<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides payroll item compliance line behavior within the WorkIntel application. */ class PayrollItemComplianceLine extends Model{protected $fillable=['payroll_item_id','workspace_id','payroll_compliance_rule_id','code','name','category','basis_amount','employee_amount','employer_amount','affects_gross','taxable','rule_snapshot'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['basis_amount'=>'decimal:2','employee_amount'=>'decimal:2','employer_amount'=>'decimal:2','affects_gross'=>'boolean','taxable'=>'boolean','rule_snapshot'=>'array'];}/** Handles the rule operation for the current WorkIntel workflow. */ public function rule():BelongsTo{return $this->belongsTo(PayrollComplianceRule::class,'payroll_compliance_rule_id');}/** Handles the item operation for the current WorkIntel workflow. */ public function item():BelongsTo{return $this->belongsTo(PayrollItem::class,'payroll_item_id');}}
